impl Solution {
    pub fn lost_permutation(b: Vec<u32>, m: usize, s: u32) -> bool {
        let sum_b: u32 = b.iter().sum();
        let target_sum = sum_b as i32 + s as i32;

        if target_sum < 0 {
            return false;
        }

        let n = ((target_sum * 2) as f64).sqrt() as i32;

        if n < 1 {
            return false;
        }

        let expected_sum = (n * (n + 1) / 2) as i32;

        if expected_sum == target_sum {
            return true;
        }

        false
    }
}

